      }
      break;
    case 20:
      if(IMX335_WriteTable(pObj, framerate_20fps_regs, ARRAY_SIZE(framerate_20fp
s_regs)) != IMX335_OK)
      {
       ret = IMX335_ERROR;
      }
      break;
    case 25:
      if(IMX335_WriteTable(pObj, framerate_25fps_regs, ARRAY_SIZE(framerate_25fp
