int stm32n6_dcmipp_start_capture(uint32_t dstaddr)
{
  clock_t start;

  if ((dstaddr & 0x0fu) != 0u)
    {
      _err("dcmipp: destination not 16-byte aligned: 0x%08lx\n",
           (unsigned long)dstaddr);
      return -EINVAL;
    }

  /* Reset the sticky diagnostics for this run */

  g_dcmipp.error_code    = 0;
  g_dcmipp.csi_err_count = 0;
  g_dcmipp.overrun_count = 0;

  /* --- Step 1 (PIPE1-FIRST): configure + activate PIPE1 BEFORE enabling
   * VC0, so PIPE1 is already consuming the moment the first sensor frame
   * arrives.  The bare-metal HAL enables VC0 first (VC0-first) which is
   * fine there because by start time the sensor has been streaming for
   * the whole ISP_Init (~100s of ms) and the receiver is already locked;
   * in NuttX the sensor has only just started (200ms delay), so a VC0-first
   * order leaves a window where the 189 MB/s stream overflows the CSI
   * clock-changer FIFO (no consumer yet), wedging the receiver
   * (CCFIFOFF stuck, no frames).  Arming PIPE1 first removes that window.
   * --- */

  DCMIPP->P1FCTCR |= 0;                  /* CPTMODE=0: continuous */
  putreg32(dstaddr, (uintptr_t)&DCMIPP->P1PPM0AR1);

  DCMIPP->CMIER |= DCMIPP_PIPE1_IT_ENABLE;
  DCMIPP->CMFCR = DCMIPP_CMSR2_P1OVRF;

  /* PIPE1 full ISP chain, aligned with the bare-metal ISP_Start order:
   *   demosaic -> decimation(f1) -> black level -> stats window -> gamma
   *   -> colorconv.  The bare-metal PIPE1 runs with ALL of these blocks
   *   enabled (IQ profile: blackLevel=12/12/12, stats full-frame, gamma
   *   on); NuttX previously ran demosaic+colorconv only, which left the
   *   PIPE1 data path in a non-reference state and caused persistent
   *   overrun (P1OVRF) once streaming began.
   */

  dcmipp_pipe1_demosaic_config();

  /* ISP decimation: factor 1 (no pixel removed), block enabled.
   * Matches HAL_DCMIPP_PIPE_SetISPDecimationConfig + EnableISPDecimation. */

  putreg32(DCMIPP_P1DECR_ENABLE, (uintptr_t)&DCMIPP->P1DECR);

  /* Black level calibration: BLCR=BLCG=BLCB=12, enabled. */

  putreg32(DCMIPP_P1BLCCR_ENABLE |
           (12u << DCMIPP_P1BLCCR_BLCR_Pos) |
           (12u << DCMIPP_P1BLCCR_BLCG_Pos) |
           (12u << DCMIPP_P1BLCCR_BLCB_Pos),
           (uintptr_t)&DCMIPP->P1BLCCR);

  /* Statistics window: full frame (0,0) 2592x1944 - the bare-metal
