/**
  * @brief  Initialize the selected HAL DCMIPP handle and associate a DCMIPP per
ipheral instance.
  * @param  hdcmipp  Pointer to DCMIPP handle
  * @retval HAL status
  */
HAL_StatusTypeDef HAL_DCMIPP_Init(DCMIPP_HandleTypeDef *hdcmipp)
{
  uint32_t pipe_index;

  /* Check pointer validity */
  if (hdcmipp == NULL)
  {
    return HAL_ERROR;
  }

  /* Check function parameters */
  assert_param(IS_DCMIPP_ALL_INSTANCE(hdcmipp->Instance));

  if (hdcmipp->State == HAL_DCMIPP_STATE_RESET)
  {
    /* Init the DCMIPP Callback settings */
#if (USE_HAL_DCMIPP_REGISTER_CALLBACKS == 1)
    /* Reset callback pointers to the weak predefined callbacks */
    hdcmipp->PIPE_FrameEventCallback = HAL_DCMIPP_PIPE_FrameEventCallback;
    hdcmipp->PIPE_VsyncEventCallback = HAL_DCMIPP_PIPE_VsyncEventCallback;
    hdcmipp->PIPE_LineEventCallback  = HAL_DCMIPP_PIPE_LineEventCallback;
    hdcmipp->PIPE_LimitEventCallback = HAL_DCMIPP_PIPE_LimitEventCallback;
    hdcmipp->PIPE_ErrorCallback      = HAL_DCMIPP_PIPE_ErrorCallback;
    hdcmipp->ErrorCallback           = HAL_DCMIPP_ErrorCallback;
    hdcmipp->LineErrorCallback         = HAL_DCMIPP_CSI_LineErrorCallback;
    hdcmipp->EndOfFrameEventCallback   = HAL_DCMIPP_CSI_EndOfFrameEventCallback;
    hdcmipp->TimerCounterEventCallback = HAL_DCMIPP_CSI_TimerCounterEventCallbac
k;
    hdcmipp->StartOfFrameEventCallback = HAL_DCMIPP_CSI_StartOfFrameEventCallbac
k;
    hdcmipp->LineByteEventCallback     = HAL_DCMIPP_CSI_LineByteEventCallback;
    hdcmipp->ClockChangerFifoFullEventCallback = HAL_DCMIPP_CSI_ClockChangerFifo
FullEventCallback;
    hdcmipp->ShortPacketDetectionEventCallback = HAL_DCMIPP_CSI_ShortPacketDetec
tionEventCallback;
    if (hdcmipp->MspInitCallback == NULL)
    {
      /* Legacy weak MspInit Callback        */
      hdcmipp->MspInitCallback = HAL_DCMIPP_MspInit;
    }
    /* Initialize the low level hardware (MSP) */
    hdcmipp->MspInitCallback(hdcmipp);
#else
    /* Init the low level hardware : GPIO, CLOCK, NVIC and DMA */
    HAL_DCMIPP_MspInit(hdcmipp);
#endif /* (USE_HAL_DCMIPP_REGISTER_CALLBACKS) */
  }

  /* Change the DCMIPP state */
  hdcmipp->State = HAL_DCMIPP_STATE_BUSY;

  /* Reset DCMIPP Pipe state */
  for (pipe_index = 0U; pipe_index < DCMIPP_NUM_OF_PIPES; pipe_index++)
  {
    hdcmipp->PipeState[pipe_index] = HAL_DCMIPP_PIPE_STATE_RESET;
  }

  /* Update error code */
  hdcmipp->ErrorCode = HAL_DCMIPP_ERROR_NONE;

  /* Update the DCMIPP state*/
  hdcmipp->State = HAL_DCMIPP_STATE_INIT;

  return HAL_OK;
}
static void DCMIPP_CSI_WritePHYReg(CSI_TypeDef *hcsi, uint32_t reg_msb, uint32_t
 reg_lsb, uint32_t val)
{
  /* Based on sequence described at section 5.2.3.2 of DesignWave document */
  /* For writing the 4-bit testcode MSBs */
  /* Set testen to high */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);

  /* Place 0x00 in testdin */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);

  /* Set testclk to low (with the falling edge on testclk, the testdin signal co
ntent is latched internally) */
  CLEAR_REG(hcsi->PTCR0);

  /* Set testen to low */
  CLEAR_REG(hcsi->PTCR1);

  /* Place the 8-bit word corresponding to the testcode MSBs in testdin */
  SET_BIT(hcsi->PTCR1, reg_msb & 0xFFU);

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);

  /* For writing the 8-bit testcode LSBs */
  /* Set testclk to low */
  CLEAR_REG(hcsi->PTCR0);

  /* Set testen to high */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);

  /* Place the 8-bit word test data in testdin */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM | (reg_lsb & 0xFFU));

  /* Set testclk to low (with the falling edge on testclk, the testdin signal co
ntent is latched internally) */
  CLEAR_REG(hcsi->PTCR0);

  /* Set testen to low */
  CLEAR_REG(hcsi->PTCR1);

  /* For writing the data */
  /* Place the 8-bit word corresponding to the page offset in testdin */
  SET_BIT(hcsi->PTCR1, val & 0xFFU);

  /* Set testclk to high (test data is programmed internally */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);

  /* Finish by setting testclk to low */
  CLEAR_REG(hcsi->PTCR0);
}

int stm32n6_imx335_start_stream(void)
{
  int ret;

  /* Start streaming (mode select = streaming) - the ALIENTEK IMX335_Init
   * writes the mode select BEFORE the input-clock (INCK) table; the INCK
   * PLL programming only takes effect once the sensor is out of standby.
   */

  ret = imx335_write_reg(g_i2c, IMX335_REG_MODE_SELECT,
                            IMX335_MODE_STREAMING);
  if (ret < 0)
    {
      return ret;
    }

  up_mdelay(20);

  /* Write the input-clock (INCK) PLL table.  The bare-metal ALIENTEK
   * demo calls IMX335_SetFrequency(IMX335_INCK_37MHZ) after the mode
   * select, programming the sensor PLL for a 37.125 MHz input clock
   * (0x300c=0x5B, 0x300d=0x40).  A previous appli.hex disassembly
   * mis-read SetFrequency(5) as an empty 6 MHz table; 5 is actually
   * IMX335_INCK_37MHZ (INCK_6MHZ is 0), so the INCK table MUST be
   * written for the MIPI output bitrate to match the DCMIPP PHY.
   */

  ret = imx335_write_table(g_i2c, g_inck_37mhz,
                           sizeof(g_inck_37mhz) /
                           sizeof(g_inck_37mhz[0]));
  if (ret < 0)
    {
      return ret;
    }

  if (g_imx335_hs_mode == 2 || g_imx335_hs_mode == 3)
    {
      ret = imx335_write_table16(g_i2c, g_hs_timing_ths,
                                 sizeof(g_hs_timing_ths) /
                                 sizeof(g_hs_timing_ths[0]));
      if (ret < 0)
        {
          return ret;
        }
    }

  up_mdelay(20);

  _info("imx335: streaming started"
        " (INCK 37MHz + HS timing mode %d written)\n", g_imx335_hs_mode);

  return OK;
}

/****************************************************************************
 * Name: stm32n6_imx335_set_hs_mode
 *
 * Description:
 *   Select the MIPI D-PHY HS transmit-timing mode for the next
 *   stm32n6_imx335_start_stream():
 *     0 = do not write any HS timing registers (sensor defaults)
 *     1 = write clock-lane group only (0x3a18-0x3a1e)
 *     2 = write data-lane group only (0x3a20-0x3a28)
 *     3 = write both groups (default)
 *
 ****************************************************************************/

void stm32n6_imx335_set_hs_mode(int mode)
{
  g_imx335_hs_mode = mode;
}

