int32_t IMX335_SetFrequency(IMX335_Object_t *pObj, int32_t frequency)
{
  uint32_t ret = IMX335_OK;

  switch (frequency)
  {
    case IMX335_INCK_74MHZ:
      if(IMX335_WriteTable(pObj, inck_74Mhz_regs, ARRAY_SIZE(inck_74Mhz_regs)) !
= IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
    case IMX335_INCK_37MHZ:
      if(IMX335_WriteTable(pObj, inck_37Mhz_regs, ARRAY_SIZE(inck_37Mhz_regs)) !
= IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
    case IMX335_INCK_27MHZ:
      if(IMX335_WriteTable(pObj, inck_27Mhz_regs, ARRAY_SIZE(inck_27Mhz_regs)) !
= IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
    case IMX335_INCK_24MHZ:
      if(IMX335_WriteTable(pObj, inck_24Mhz_regs, ARRAY_SIZE(inck_24Mhz_regs)) !
= IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
    case IMX335_INCK_18MHZ:
      if(IMX335_WriteTable(pObj, inck_18Mhz_regs, ARRAY_SIZE(inck_18Mhz_regs)) !
= IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
    default:
      /* IMX335_INCK_6MHZ */
      if(IMX335_WriteTable(pObj, inck_6Mhz_regs, ARRAY_SIZE(inck_6Mhz_regs)) !=
IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      break;
  };

  return ret;
}

