int32_t IMX335_Init(IMX335_Object_t *pObj, uint32_t Resolution, uint32_t PixelFo
rmat)
{
  int32_t ret = IMX335_OK;
  uint8_t tmp;

  if(pObj->IsInitialized == 0U)
  {
    switch (Resolution)
    {
      case IMX335_R2592_1944:
        if(IMX335_WriteTable(pObj, res_2592_1944_regs, ARRAY_SIZE(res_2592_1944_
regs)) != IMX335_OK)
        {
          ret = IMX335_ERROR;
        }
        break;
      /* Add new resolution here */
      default:
        /* Resolution not supported */
        ret = IMX335_ERROR;
    }

    if(!ret)
    {
      if(IMX335_WriteTable(pObj, mode_2l_10b_regs, ARRAY_SIZE(mode_2l_10b_regs))
 != IMX335_OK)
      {
        ret = IMX335_ERROR;
      }
      else
      {
        /* Start streaming */
        tmp = IMX335_MODE_STREAMING;
        if(imx335_write_reg(&pObj->Ctx, IMX335_REG_MODE_SELECT, &tmp, 1) != IMX3
35_OK)
        {
          ret = IMX335_ERROR;
        }
        else
        {
          IMX335_Delay(pObj, 20);
          pObj->IsInitialized = 1U;
        }
      }
    }
  }

  return ret;
}

int stm32n6_dcmipp_start_capture(uint32_t dstaddr)
{
  clock_t start;

  if ((dstaddr & 0x0fu) != 0u)
    {
      _err("dcmipp: destination not 16-byte aligned: 0x%08lx\n",
           (unsigned long)dstaddr);
      return -EINVAL;
    }

  /* Reset the sticky diagnostics for this run */

  g_dcmipp.error_code    = 0;
  g_dcmipp.csi_err_count = 0;
  g_dcmipp.overrun_count = 0;

  /* --- Step 1 (PIPE1-FIRST): configure + activate PIPE1 BEFORE enabling
   * VC0, so PIPE1 is already consuming the moment the first sensor frame
   * arrives.  The bare-metal HAL enables VC0 first (VC0-first) which is
   * fine there because by start time the sensor has been streaming for
   * the whole ISP_Init (~100s of ms) and the receiver is already locked;
   * in NuttX the sensor has only just started (200ms delay), so a VC0-first
   * order leaves a window where the 189 MB/s stream overflows the CSI
   * clock-changer FIFO (no consumer yet), wedging the receiver
   * (CCFIFOFF stuck, no frames).  Arming PIPE1 first removes that window.
   * --- */

  DCMIPP->P1FCTCR |= 0;                  /* CPTMODE=0: continuous */
  putreg32(dstaddr, (uintptr_t)&DCMIPP->P1PPM0AR1);

  DCMIPP->CMIER |= DCMIPP_PIPE1_IT_ENABLE;
  DCMIPP->CMFCR = DCMIPP_CMSR2_P1OVRF;

  /* PIPE1 full ISP chain, aligned with the bare-metal ISP_Start order:
   *   demosaic -> decimation(f1) -> black level -> stats window -> gamma
   *   -> colorconv.  The bare-metal PIPE1 runs with ALL of these blocks
   *   enabled (IQ profile: blackLevel=12/12/12, stats full-frame, gamma
   *   on); NuttX previously ran demosaic+colorconv only, which left the
   *   PIPE1 data path in a non-reference state and caused persistent
   *   overrun (P1OVRF) once streaming began.
   */

  dcmipp_pipe1_demosaic_config();

  /* ISP decimation: factor 1 (no pixel removed), block enabled.
   * Matches HAL_DCMIPP_PIPE_SetISPDecimationConfig + EnableISPDecimation. */

  putreg32(DCMIPP_P1DECR_ENABLE, (uintptr_t)&DCMIPP->P1DECR);

  /* Black level calibration: BLCR=BLCG=BLCB=12, enabled. */

  putreg32(DCMIPP_P1BLCCR_ENABLE |
           (12u << DCMIPP_P1BLCCR_BLCR_Pos) |
           (12u << DCMIPP_P1BLCCR_BLCG_Pos) |
           (12u << DCMIPP_P1BLCCR_BLCB_Pos),
           (uintptr_t)&DCMIPP->P1BLCCR);

  /* Statistics window: full frame (0,0) 2592x1944 - the bare-metal
   * application passes X0=0/Y0=0/XSize=2592/YSize=1944 to ISP_Init and
   * ISP_Start uses it (decimation factor 1 => same coordinates). */

  putreg32(0u, (uintptr_t)&DCMIPP->P1STSTR);   /* HStart=0, VStart=0 */

  putreg32(DCMIPP_P1STSZR_CROPEN |
           (2592u << DCMIPP_P1STSZR_HSIZE_Pos) |
           (1944u << DCMIPP_P1STSZR_VSIZE_Pos),
           (uintptr_t)&DCMIPP->P1STSZR);

  /* Gamma conversion: enable (bare-metal uses the default/reset LUT). */

  DCMIPP->P1GMCR |= DCMIPP_P1GMCR_ENABLE;

  dcmipp_pipe1_colorconv_config();

  DCMIPP->P1FSCR |= DCMIPP_P1FSCR_PIPEN;
  DCMIPP->P1FCTCR |= DCMIPP_P1FCTCR_CPTREQ;

  /* DIAG (2026-08-23): read back the instant after CPTREQ is set.  This
   * distinguishes "CPTREQ never took" (hardware rejects the request ->
   * P1FCTCR stays 0 / P1CPTACT stays 0) from "CPTREQ accepted, capture
   * started, then failed" (P1FCTCR=8 / P1CPTACT=1, collapses later). */
  _info("dcmipp: after CPTREQ: P1FCTCR=0x%08lx CMSR1=0x%08lx CMSR2=0x%08lx\n",
        (unsigned long)DCMIPP->P1FCTCR,
        (unsigned long)DCMIPP->CMSR1,
        (unsigned long)DCMIPP->CMSR2);

  /* --- Step 2: clear stale CSI flags, enable VC0.  NOTE: the sensor may
   * NOT be streaming yet (new order: capture armed BEFORE start_stream).
   * The VC0STATEF wait therefore tolerates timeout; stm32n6_dcmipp_wait_vc0()
   * is called by the application after the sensor starts streaming. --- */

  CSI->FCR0 = 0xffffffffu;
  CSI->FCR1 = 0xffffffffu;

  CSI->CR |= CSI_CR_VC0START;

  /* (2026-08-24) The sensor is ALREADY streaming (mid-frame) at this
   * point, so the receiver may immediately flag SYNCERR on the partial
   * frame and that sticky flag blocks every later frame (CPTACT=0,
   * frames=0 - observed).  Clear all CSI flags so the receiver re-syncs
   * on the NEXT SOF, then wait for that SOF, re-clearing SYNCERR/CCFIFO
   * if they reappear before it (mid-frame garbage).  Once SOF0F is seen
   * the receiver is frame-locked and subsequent frames flow cleanly. */

  start = clock_systime_ticks();
  while ((CSI->SR0 & CSI_SR0_SOF0F) == 0u)
    {
      uint32_t sr0 = CSI->SR0;

      if ((sr0 & (CSI_SR0_SYNCERRF | CSI_SR0_CCFIFOFF)) != 0u)
        {
          CSI->FCR0 = sr0 & (CSI_SR0_SYNCERRF | CSI_SR0_CCFIFOFF);
        }

      if (clock_systime_ticks() - start > MSEC2TICK(300))
        {
          _info("dcmipp: SOF0F timeout SR0=0x%08lx "
                "(receiver not frame-locked)\n",
                (unsigned long)CSI->SR0);
          break;
        }
    }

  _info("dcmipp: after VC0START: SR0=0x%08lx SR1=0x%08lx\n",
        (unsigned long)CSI->SR0, (unsigned long)CSI->SR1);

  /* --- Step 3 (2026-08-23): enable ONLY the SOF/EOF interrupts.  The
   * CSI error interrupts (SYNCERR/CCFIFO/CRC/ECC...) are NOT enabled:
   * while the D-PHY/CSI data path is unhealthy (CRC errors observed),
   * arming the error interrupts floods the CPU (ISR storm) and hangs the
   * shell (cam status/diag freeze).  Bare-metal arms them because its
   * stream is clean; NuttX must first fix the CRC errors. --- */

  CSI->IER0 |= CSI_IER0_SOF0IE | CSI_IER0_EOF0IE;
  CSI->IER1 = 0u;
  CSI->FCR0 = 0xffffffffu;
  CSI->FCR1 = 0xffffffffu;

  _info("dcmipp: PIPE1 capture -> 0x%08lx\n",
        (unsigned long)dstaddr);

  return OK;
}

