wait_vc0 加等 SOF：
```c
int stm32n6_dcmipp_wait_vc0(void)
{
  clock_t start;

  /* (2026-08-25 P0) Capture-first order: VC0 was armed before the sensor
   * started, so VC0STATEF only sets once the sensor streams.  Wait for it,
   * then wait for the first clean SOF (clearing SYNCERR/CCFIFO if they
   * appear on the partial frame). */

  start = clock_systime_ticks();
  while ((CSI->SR0 & CSI_SR0_VC0STATEF) == 0u)
    {
      if (clock_systime_ticks() - start > MSEC2TICK(1000))
        {
          _err("dcmipp: VC0STATEF timeout SR0=0x%08lx SR1=0x%08lx\n",
               (unsigned long)CSI->SR0, (unsigned long)CSI->SR1);
          return -ETIMEDOUT;
        }
    }

  _info("dcmipp: VC0 active SR0=0x%08lx SR1=0x%08lx\n",
        (unsigned long)CSI->SR0, (unsigned long)CSI->SR1);

  /* Wait for the first SOF (frame start) once VC0 is active. */

  start = clock_systime_ticks();
  while ((CSI->SR0 & CSI_SR0_SOF0F) == 0u)
    {
      uint32_t sr0 = CSI->SR0;

      if ((sr0 & (CSI_SR0_SYNCERRF | CSI_SR0_CCFIFOFF)) != 0u)
        {
          CSI->FCR0 = sr0 & (CSI_SR0_SYNCERRF | CSI_SR0_CCFIFOFF);
        }

      if (clock_systime_ticks() - start > MSEC2TICK(1000))
        {
          _err("dcmipp: SOF0F timeout SR0=0x%08lx (no frame start)\n",
               (unsigned long)CSI->SR0);
          return -ETIMEDOUT;
        }
    }

  _info("dcmipp: first SOF received SR0=0x%08lx\n",
        (unsigned long)CSI->SR0);

  return OK;
}
```

