/****************************************************************************
 * Name: cam_status
 *
 ****************************************************************************/

static void cam_status(void)
{
  uint32_t fbaddr;
  FAR uint16_t *fb;

  printf("cam: frames captured: %lu\n",
         (unsigned long)stm32n6_dcmipp_get_frame_count());
  printf("cam: pipe1 overruns: %lu\n",
         (unsigned long)stm32n6_dcmipp_get_overrun_count());

  /* Read the first framebuffer pixels to verify PIPE1 actually wrote.
   * 0xf800 = the fbcolor red fill would still be present if PIPE1 never
   * wrote to the live buffer.
   */

  if (cam_get_framebuffer(&fbaddr) == 0)
    {
      int row;
      int col;
      int nz;

      fb = (FAR uint16_t *)(uintptr_t)fbaddr;

      /* Multi-row / multi-column sample: how much of the framebuffer did
       * PIPE1 actually write?  A "one-line streak" on the LCD means only a
       * few rows are non-zero (partial write); a full 800x480 capture
       * shows non-zero across all sampled rows. */

      printf("cam: fb[0x%08lx] sample (row,col: px):\n", (unsigned long)fbaddr);
      for (row = 0; row < 480; row += 100)
        {
          printf("cam:   row %3d col0-7:", row);
          nz = 0;
          for (col = 0; col < 8; col++)
            {
              printf(" %04x", fb[row * 800 + col]);
              if (fb[row * 800 + col] != 0) nz++;
            }

          printf(" | x200:%04x x400:%04x x600:%04x (nz=%d)\n",
                 fb[row * 800 + 200], fb[row * 800 + 400],
                 fb[row * 800 + 600], nz);
        }

      /* Row 479 (last) as well */

      printf("cam:   row 479:");
      for (col = 0; col < 800; col += 200)
        {
          printf(" %04x", fb[479 * 800 + col]);
        }

      printf("\n");
    }

  /* Sample CSI SR0 30 times: tells whether the sensor keeps streaming
   * (SOF0F = frame start packets seen, VC0STATEF = VC0 active).
   */

  cam_sample_csi();

  /* NOTE: do not read IMX335 registers here - the I2C read hangs once the
   * sensor has been streaming for a while.  Only DCMIPP/CSI (memory-mapped)
   * status is shown.
   */

  stm32n6_dcmipp_dump_status();
}

/****************************************************************************
 * Name: cam_diag
 *
 * Description:
 *   Dump the CSI-2 / DCMIPP status registers and read back a few IMX335
 *   registers to confirm the sensor is streaming.
 *
 ****************************************************************************/

static void cam_diag(void)
{

/* PIPE1 full ISP chain, aligned with the bare-metal ISP_Start order:
 *   demosaic -> decimation(f1) -> black level -> stats window -> gamma
 *   -> colorconv. */

dcmipp_pipe1_demosaic_config();
putreg32(DCMIPP_P1DECR_ENABLE, (uintptr_t)&DCMIPP->P1DECR);

putreg32(DCMIPP_P1BLCCR_ENABLE |
         (12u << DCMIPP_P1BLCCR_BLCR_Pos) |
         (12u << DCMIPP_P1BLCCR_BLCG_Pos) |
         (12u << DCMIPP_P1BLCCR_BLCB_Pos),
         (uintptr_t)&DCMIPP->P1BLCCR);

putreg32(0u, (uintptr_t)&DCMIPP->P1STSTR);   /* HStart=0, VStart=0 */

putreg32(DCMIPP_P1STSZR_CROPEN |
         (2592u << DCMIPP_P1STSZR_HSIZE_Pos) |
         (1944u << DCMIPP_P1STSZR_VSIZE_Pos),
         (uintptr_t)&DCMIPP->P1STSZR);

DCMIPP->P1GMCR |= DCMIPP_P1GMCR_ENABLE;

dcmipp_pipe1_colorconv_config();

/* --- Step 2: clear stale CSI flags, enable VC0 FIRST. --- */

CSI->FCR0 = 0xffffffffu;
CSI->FCR1 = 0xffffffffu;

CSI->CR |= CSI_CR_VC0START;

/* (2026-08-25 P0) CAPTURE-FIRST: the sensor is NOT streaming yet, so
 * VC0STATEF is expected to stay 0 here - do NOT error out.  The
 * application starts the sensor right after start_capture() and then
 * confirms VC0 + first frame via stm32n6_dcmipp_wait_vc0(). */

start = clock_systime_ticks();
while ((CSI->SR0 & CSI_SR0_VC0STATEF) == 0u)
  {
    if (clock_systime_ticks() - start > MSEC2TICK(50))
      {
        _info("dcmipp: VC0STATEF not set yet (sensor not streaming), "
              "continuing\n");
        break;
      }
  }

_info("dcmipp: after VC0START: SR0=0x%08lx SR1=0x%08lx\n",
      (unsigned long)CSI->SR0, (unsigned long)CSI->SR1);

/* --- Step 3: NOW arm PIPE1 (PIPEN + CPTREQ).  VC0 is already routing
 * data, so PIPE1 consumes immediately - CCFIFO stays drained. --- */

DCMIPP->P1FSCR |= DCMIPP_P1FSCR_PIPEN;

