for idx, l in enumerate(lines):
    try:
        d = json.loads(l)
    except Exception:
        continue
    role = d.get('role', '')
    c = d.get('content', '')
    texts = []
    tools = []
    if isinstance(c, list):
        for x in c:
            if not isinstance(x, dict):
                continue
            if x.get('type') == 'text':
