            hits.append(idx)
    print(f'  "{kw}": {len(hits)} user-msg hits -> {hits[:10]}')

#!/usr/bin/env python3
"""Scan the copilot transcript (assistant.message / user.message format)."""
import json, sys

path = '/home/leihann/.config/Code/User/workspaceStorage/202a05467ceff63220c526b288d9ea8b/GitHub.copilot-chat/transcripts/f17a355a-27c8-48cb-bf90-e6cc23faca00.jsonl'

lines = open(path, encoding='utf-8', errors='replace').readlines()
print('total lines:', len(lines))

def get_text(d):
    """Extract text content from a message dict regardless of shape."""
    out = []
    def walk(o):
        if isinstance(o, str):
            out.append(o)
        elif isinstance(o, dict):
            for k in ('content', 'text', 'message', 'data'):
                if k in o:
                    walk(o[k])
        elif isinstance(o, list):
            for x in o:
                walk(x)
    walk(d)
    return '\n'.join(out)

msgs = []  # (idx, type, text)
for idx, l in enumerate(lines):
    try:
        d = json.loads(l)
    except Exception:
        continue
    t = d.get('type', '')
    if t == 'user.message':
        txt = get_text(d)
        msgs.append((idx, 'USER', txt))
    elif t == 'assistant.message':
        txt = ''
        data = d.get('data', {})
        c = data.get('content', '')
        if isinstance(c, str):
            txt = c
        tools = []
        for tr in data.get('toolRequests', []) or []:
            if isinstance(tr, dict):
                tools.append(tr.get('name', ''))
        msgs.append((idx, 'ASST', txt, tools))

# Timeline: user messages
print('\n=== USER MESSAGES TIMELINE ===')
for idx, t, *rest in msgs:
    if t == 'USER':
        txt = rest[0]
        one = ' '.join(txt.split())[:160]
        print(f'[{idx}] USER: {one}')

# Keyword search across user messages
print('\n=== KEYWORD HITS (user msgs) ===')
keywords = ['ERR1', 'frames', '110', 'ETIMEDOUT', '24 MHz', '37 MHz', '24MHz',
            '37MHz', 'INCK', '间歇', '时好时坏', 'overrun', '0x2b', 'PHY',
            'PHY1600', '1600', '裸机', '金标准', '清屏', '黑屏', '花屏']
for kw in keywords:
    hits = [idx for idx, t, *r in msgs
            if t == 'USER' and kw.lower() in r[0].lower()]
    print(f'  "{kw}": {len(hits)} -> {hits[:12]}')

